def to_root(t, key):             # amortized O(log n)
    if t is None or t.key == key:
        return t
    if key < t.key:
        if t.left is None: return t
        if key < t.left.key:                      # zig-zig
            t.left.left = to_root(t.left.left, key)
            t = rot_right(t)
        elif key > t.left.key:                    # zig-zag
            t.left.right = to_root(t.left.right, key)
            if t.left.right: t.left = rot_left(t.left)
        return t if t.left is None else rot_right(t)
    if t.right is None: return t
    if key > t.right.key:
        t.right.right = to_root(t.right.right, key)
        t = rot_left(t)
    elif key < t.right.key:
        t.right.left = to_root(t.right.left, key)
        if t.right.left: t.right = rot_right(t.right)
    return t if t.right is None else rot_left(t)

