class Cell:
    CAP = 4

    def __init__(self, x, y, size):
        self.x, self.y, self.size = x, y, size
        self.points = []
        self.kids = None             # NW, NE, SW, SE once split

    def add(self, p):
        if self.kids is None:
            self.points.append(p)
            if len(self.points) > self.CAP:
                self._split()
            return
        self._child_for(p).add(p)

    def _split(self):
        h = self.size / 2
        self.kids = [Cell(self.x + dx, self.y + dy, h)
                     for dy in (0, h) for dx in (0, h)]
        for p in self.points:
            self._child_for(p).add(p)
        self.points = []

    def _child_for(self, p):
        h = self.size / 2
        i = (p[0] >= self.x + h) + 2 * (p[1] >= self.y + h)
        return self.kids[i]

